     Relating to IETF Documents
     (http://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 6470; see
     the RFC itself for full legal notices.";

  revision 2012-02-06;

  notification netconf-config-change {
    status current;
    description
      "Generated when the NETCONF server detects that the
       <running> or <startup> configuration datastore
       has been changed by a management session.
       The notification summarizes the edits that
       have been detected.

       The server MAY choose to also generate this
       notification while loading a datastore during the
       boot process for the device.";
    container changed-by {
      status current;
      description
        "Indicates the source of the change.
         If caused by internal action, then the
         empty leaf 'server' will be present.
         If caused by a management session, then
         the name, remote host address, and session ID
         of the session that made the change will be reported.";
      choice server-or-user {
        mandatory true;
        status current;
        case server {
          status current;
          leaf server {
            type empty;
            status current;
            description
              "If present, the change was caused
               by the server.";
          }
        }
        case by-user {
          status current;
          leaf username {
            type string;
            mandatory true;
            status current;
            description
              "Name of the user for the session.";
          }
          leaf session-id {
            type uint32;
            mandatory true;
            status current;
            description
              "Identifier of the session.
               A NETCONF session MUST be identified by a non-zero value.
               A non-NETCONF session MAY be identified by the value zero.";
          }
          leaf source-host {
            type union {
              type string {
                pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              }
              type string {
                pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              }
            }
            status current;
            description
              "Address of the remote host for the session.";
          }
        }
      }
    }
    leaf datastore {
      type enumeration {
        enum "running" {
          value 0;
          status current;
          description
            "The <running> datastore has changed.";
        }
        enum "startup" {
          value 1;
          status current;
          description
            "The <startup> datastore has changed";
        }
      }
      default "running";
      status current;
      description
        "Indicates which configuration datastore has changed.";
    }
    list edit {
      min-elements 0;
      max-elements 4294967295;
      ordered-by user;
      status current;
      description
        "An edit record SHOULD be present for each distinct
         edit operation that the server has detected on
         the target datastore.  This list MAY be omitted
         if the detailed edit operations are not known.
         The server MAY report entries in this list for
         changes not made by a NETCONF session (e.g., CLI).";
      leaf target {
        type instance-identifier {
          require-instance true;
        }
        status current;
        description
          "Topmost node associated with the configuration change.
           A server SHOULD set this object to the node within
           the datastore that is being altered.  A server MAY
           set this object to one of the ancestors of the actual
           node that was changed, or omit this object, if the
           exact node is not known.";
      }
      leaf operation {
        type enumeration {
          enum "merge" {
            value 0;
            status current;
            description
              "The configuration data identified by the
               element containing this attribute is merged
               with the configuration at the corresponding
               level in the configuration datastore identified
               by the target parameter.";
          }
          enum "replace" {
            value 1;
            status current;
            description
              "The configuration data identified by the element
               containing this attribute replaces any related
               configuration in the configuration datastore
               identified by the target parameter.  If no such
               configuration data exists in the configuration
               datastore, it is created.  Unlike a
               <copy-config> operation, which replaces the
               entire target configuration, only the configuration
               actually present in the config parameter is affected.";
          }
          enum "create" {
            value 2;
            status current;
            description
              "The configuration data identified by the element
               containing this attribute is added to the
               configuration if and only if the configuration
               data does not already exist in the configuration
               datastore.  If the configuration data exists, an
               <rpc-error> element is returned with an
               <error-tag> value of 'data-exists'.";
          }
          enum "delete" {
            value 3;
            status current;
            description
              "The configuration data identified by the element
               containing this attribute is deleted from the
               configuration if and only if the configuration
               data currently exists in the configuration
               datastore.  If the configuration data does not
               exist, an <rpc-error> element is returned with
               an <error-tag> value of 'data-missing'.";
          }
          enum "remove" {
            value 4;
            status current;
            description
              "The configuration data identified by the element
               containing this attribute is deleted from the
               configuration if the configuration
               data currently exists in the configuration
               datastore.  If the configuration data does not
               exist, the 'remove' operation is silently ignored
               by the server.";
          }
        }
        default "merge";
        status current;
        description
          "Type of edit operation performed.
           A server MUST set this object to the NETCONF edit
           operation performed on the target datastore.";
      }
    }
  }
  notification netconf-capability-change {
    status current;
    description
      "Generated when the NETCONF server detects that
       the server capabilities have changed.
       Indicates which capabilities have been added, deleted,
       and/or modified.  The manner in which a server
       capability is changed is outside the scope of this
       document.";
    container changed-by {
      status current;
      description
        "Indicates the source of the change.
         If caused by internal action, then the
         empty leaf 'server' will be present.
         If caused by a management session, then
         the name, remote host address, and session ID
         of the session that made the change will be reported.";
      choice server-or-user {
        mandatory true;
        status current;
        case server {
          status current;
          leaf server {
            type empty;
            status current;
            description
              "If present, the change was caused
               by the server.";
          }
        }
        case by-user {
          status current;
          leaf username {
            type string;
            mandatory true;
            status current;
            description
              "Name of the user for the session.";
          }
          leaf session-id {
            type uint32;
            mandatory true;
            status current;
            description
              "Identifier of the session.
               A NETCONF session MUST be identified by a non-zero value.
               A non-NETCONF session MAY be identified by the value zero.";
          }
          leaf source-host {
            type union {
              type string {
                pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
              }
              type string {
                pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
                pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
              }
            }
            status current;
            description
              "Address of the remote host for the session.";
          }
        }
      }
    }
    leaf-list added-capability {
      type string {
        pattern "[a-z][a-z0-9+.-]*:.*";
      }
      min-elements 0;
      max-elements 4294967295;
      ordered-by user;
      status current;
      description
        "List of capabilities that have just been added.";
    }
    leaf-list deleted-capability {
      type string {
        pattern "[a-z][a-z0-9+.-]*:.*";
      }
      min-elements 0;
      max-elements 4294967295;
      ordered-by user;
      status current;
      description
        "List of capabilities that have just been deleted.";
    }
    leaf-list modified-capability {
      type string {
        pattern "[a-z][a-z0-9+.-]*:.*";
      }
      min-elements 0;
      max-elements 4294967295;
      ordered-by user;
      status current;
      description
        "List of capabilities that have just been modified.
         A capability is considered to be modified if the
         base URI for the capability has not changed, but
         one or more of the parameters encoded at the end of
         the capability URI have changed.
         The new modified value of the complete URI is returned.";
    }
  }
  notification netconf-session-start {
    status current;
    description
      "Generated when a NETCONF server detects that a
       NETCONF session has started.  A server MAY generate
       this event for non-NETCONF management sessions.
       Indicates the identity of the user that started
       the session.";
    leaf username {
      type string;
      mandatory true;
      status current;
      description
        "Name of the user for the session.";
    }
    leaf session-id {
      type uint32;
      mandatory true;
      status current;
      description
        "Identifier of the session.
         A NETCONF session MUST be identified by a non-zero value.
         A non-NETCONF session MAY be identified by the value zero.";
    }
    leaf source-host {
      type union {
        type string {
          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
        }
        type string {
          pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
          pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
        }
      }
      status current;
      description
        "Address of the remote host for the session.";
    }
  }
  notification netconf-session-end {
    status current;
    description
      "Generated when a NETCONF server detects that a
       NETCONF session has terminated.
       A server MAY optionally generate this event for
       non-NETCONF management sessions.  Indicates the
       identity of the user that owned the session,
       and why the session was terminated.";
    leaf username {
      type string;
      mandatory true;
      status current;
      description
        "Name of the user for the session.";
    }
    leaf session-id {
      type uint32;
      mandatory true;
      status current;
      description
        "Identifier of the session.
         A NETCONF session MUST be identified by a non-zero value.
         A non-NETCONF session MAY be identified by the value zero.";
    }
    leaf source-host {
      type union {
        type string {
          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
        }
        type string {
          pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
          pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
        }
      }
      status current;
      description
        "Address of the remote host for the session.";
    }
    leaf killed-by {
      when "../termination-reason = 'killed'";
      type uint32 {
        range "1..4294967295";
      }
      status current;
      description
        "The ID of the session that directly caused this session
         to be abnormally terminated.  If this session was abnormally
         terminated by a non-NETCONF session unknown to the server,
         then this leaf will not be present.";
    }
    leaf termination-reason {
      type enumeration {
        enum "closed" {
          value 0;
          status current;
          description
            "The session was terminated by the client in normal
             fashion, e.g., by the NETCONF <close-session>
             protocol operation.";
        }
        enum "killed" {
          value 1;
          status current;
          description
            "The session was terminated in abnormal
             fashion, e.g., by the NETCONF <kill-session>
             protocol operation.";
        }
        enum "dropped" {
          value 2;
          status current;
          description
            "The session was terminated because the transport layer
             connection was unexpectedly closed.";
        }
        enum "timeout" {
          value 3;
          status current;
          description
            "The session was terminated because of inactivity,
             e.g., waiting for the <hello> message or <rpc>
             messages.";
        }
        enum "bad-hello" {
          value 4;
          status current;
          description
            "The client's <hello> message was invalid.";
        }
        enum "other" {
          value 5;
          status current;
          description
            "The session was terminated for some other reason.";
        }
      }
      mandatory true;
      status current;
      description
        "Reason the session was terminated.";
    }
  }
  notification netconf-confirmed-commit {
    status current;
    description
      "Generated when a NETCONF server detects that a
       confirmed-commit event has occurred.  Indicates the event
       and the current state of the confirmed-commit procedure
       in progress.";
    reference
      "RFC 6241, Section 8.4";
    leaf username {
      when "../confirm-event != 'timeout'";
      type string;
      mandatory true;
      status current;
      description
        "Name of the user for the session.";
    }
    leaf session-id {
      when "../confirm-event != 'timeout'";
      type uint32;
      mandatory true;
      status current;
      description
        "Identifier of the session.
         A NETCONF session MUST be identified by a non-zero value.
         A non-NETCONF session MAY be identified by the value zero.";
    }
    leaf source-host {
      when "../confirm-event != 'timeout'";
      type union {
        type string {
          pattern "(([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9][0-9]|2[0-4][0-9]|25[0-5])(%.+)?";
        }
        type string {
          pattern "((:|[0-9a-fA-F]{0,4}):)([0-9a-fA-F]{0,4}:){0,5}((([0-9a-fA-F]{0,4}:)?(:|[0-9a-fA-F]{0,4}))|(((25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9]?[0-9])))(%[A-Za-z0-9][A-Za-z0-9\\-\\._~/]*)?";
          pattern "(([^:]+:){6}(([^:]+:[^:]+)|(.*\\..*)))|((([^:]+:)*[^:]+)?::(([^:]+:)*[^:]+)?)(%.+)?";
        }
      }
      status current;
      description
        "Address of the remote host for the session.";
    }
    leaf confirm-event {
      type enumeration {
        enum "start" {
          value 0;
          status current;
          description
            "The confirmed-commit procedure has started.";
        }
        enum "cancel" {
          value 1;
          status current;
          description
            "The confirmed-commit procedure has been canceled,
             e.g., due to the session being terminated, or an
             explicit <cancel-commit> operation.";
        }
        enum "timeout" {
          value 2;
          status current;
          description
            "The confirmed-commit procedure has been canceled
             due to the confirm-timeout interval expiring.
             The common session parameters will not be present
             in this sub-mode.";
        }
        enum "extend" {
          value 3;
          status current;
          description
            "The confirmed-commit timeout has been extended,
             e.g., by a new <confirmed-commit> operation.";
        }
        enum "complete" {
          value 4;
          status current;
          description
            "The confirmed-commit procedure has been completed.";
        }
      }
      mandatory true;
      status current;
      description
        "Indicates the event that caused the notification.";
    }
    leaf timeout {
      when "../confirm-event = 'start' or ../confirm-event = 'extend'";
      type uint32;
      units "seconds";
      status current;
      description
        "The configured timeout value if the event type
         is 'start' or 'extend'.  This value represents
         the approximate number of seconds from the event
         time when the 'timeout' event might occur.";
    }
  }
}
